#include <stdio.h>
typedef struct Axis6W8Row { unsigned int lane, frontier, spill; int delta; } Axis6W8Row;
typedef struct Axis6W8Agg { unsigned int frontier[5], spill[5]; int value[5]; } Axis6W8Agg;
static unsigned int mix8(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear8(Axis6W8Agg* a){ for(int i=0;i<5;++i){ a->frontier[i]=0u; a->spill[i]=0u; a->value[i]=0; } }
static void absorb8(Axis6W8Agg* a,const Axis6W8Row* r){ unsigned int lane=r->lane%5u; if(r->frontier<a->frontier[lane]) return; if(r->frontier>a->frontier[lane]){ a->frontier[lane]=r->frontier; a->spill[lane]=r->spill; a->value[lane]=r->delta; return; } if(r->spill>a->spill[lane]){ a->spill[lane]=r->spill; a->value[lane]=r->delta; } else if(r->spill==a->spill[lane]) a->value[lane]+=r->delta; }
static unsigned int sig8(const Axis6W8Agg* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<5u; ++lane){ h=mix8(h,lane+1u); h=mix8(h,a->frontier[lane]); h=mix8(h,a->spill[lane]); h=mix8(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const Axis6W8Row rows[]={{0u,2u,1u,4},{1u,3u,2u,5},{2u,1u,3u,7},{3u,2u,4u,3},{4u,1u,2u,6},{0u,5u,2u,6},{1u,4u,3u,-1},{2u,5u,2u,8},{3u,4u,5u,2},{4u,5u,3u,4},{0u,5u,2u,-2},{1u,4u,3u,4},{2u,5u,4u,1},{3u,4u,5u,-3},{4u,5u,3u,-1},{0u,6u,4u,5},{1u,6u,5u,3},{2u,6u,4u,6},{3u,6u,6u,1},{4u,6u,2u,2}}; Axis6W8Agg d,p; clear8(&d); for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i) absorb8(&d,&rows[i]); clear8(&p); for(unsigned int frontier=1u; frontier<=6u; ++frontier) for(unsigned int spill=1u; spill<=6u; ++spill) for(unsigned int lane=0; lane<5u; ++lane){ int merged=0,saw=0; for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i){ if(rows[i].lane%5u!=lane || rows[i].frontier!=frontier || rows[i].spill!=spill) continue; merged+=rows[i].delta; saw=1; } if(saw){ Axis6W8Row row={lane,frontier,spill,merged}; absorb8(&p,&row); } } { unsigned int sd=sig8(&d), sp=sig8(&p); printf("%u %u %u\n", sd, sp, (sd==sp)?1u:0u); } return 0; }
